package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for BrentSolver.solve(UnivariateRealFunction, double, double, double)
 * aimed at maximizing branch and line coverage.
 */
public class BrentSolver_solve_TriageGen4Test {

    private BrentSolver solver;

    @Before
    public void setUp() {
        solver = new BrentSolver();
    }

    /**
     * Tests the case where the initial guess is already a root.
     * Covers: Math.abs(yInitial) <= functionValueAccuracy
     */
    @Test
    public void testSolve_InitialIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 5. Root is 5.
        UnivariateRealFunction f = x -> x - 5.0;
        double min = 0.0;
        double max = 10.0;
        double initial = 5.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(5.0, result, 1e-10);
    }

    /**
     * Tests the case where the min endpoint is already a root.
     * Covers: Math.abs(yMin) <= functionValueAccuracy
     */
    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x. Root is 0.
        UnivariateRealFunction f = x -> x;
        double min = 0.0;
        double max = 10.0;
        double initial = 5.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(0.0, result, 1e-10);
    }

    /**
     * Tests the case where the initial guess and min endpoint bracket the root.
     * Covers: yInitial * yMin < 0
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 2. Root is 2.
        // min = 0 (y=-2), initial = 3 (y=1). Root is between 0 and 3.
        UnivariateRealFunction f = x -> x - 2.0;
        double min = 0.0;
        double max = 5.0;
        double initial = 3.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(2.0, result, 1e-10);
    }

    /**
     * Tests the case where the max endpoint is already a root.
     * Covers: Math.abs(yMax) <= functionValueAccuracy
     */
    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 10. Root is 10.
        UnivariateRealFunction f = x -> x - 10.0;
        double min = 0.0;
        double max = 10.0;
        double initial = 5.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(10.0, result, 1e-10);
    }

    /**
     * Tests the case where the initial guess and max endpoint bracket the root.
     * Covers: yInitial * yMax < 0
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 8. Root is 8.
        // min = 0 (y=-8), initial = 5 (y=-3), max = 10 (y=2). Root is between 5 and 10.
        UnivariateRealFunction f = x -> x - 8.0;
        double min = 0.0;
        double max = 10.0;
        double initial = 5.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(8.0, result, 1e-10);
    }

    /**
     * Tests the case where the function does not bracket the root (yMin * yMax > 0).
     * Covers: yMin * yMax > 0
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_NoBracketing() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x^2 + 1 (No real roots, yMin and yMax will have same sign)
        UnivariateRealFunction f = x -> x * x + 1.0;
        double min = -1.0;
        double max = 1.0;
        double initial = 0.0;

        solver.solve(f, min, max, initial);
    }

    /**
     * Tests the case where the full Brent algorithm is triggered.
     * Covers the final fallback call to solve (recursive/full Brent).
     */
    @Test
    public void testSolve_FullBrent() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = sin(x). Root at PI.
        // min = -1, max = 4, initial = 2.
        // yMin = sin(-1) < 0, yMax = sin(4) < 0, yInitial = sin(2) > 0.
        // This should trigger the logic where initial and max bracket or similar.
        UnivariateRealFunction f = Math::sin;
        double min = -1.0;
        double max = 4.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(Math.PI, result, 1e-10);
    }

    /**
     * Tests the verification of the sequence (min, initial, max).
     * Covers: verifySequence(min, initial, max)
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidSequence() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x;
        // min must be < initial < max. Providing min > max should trigger exception.
        solver.solve(f, 10.0, 0.0, 5.0);
    }
}
